import { fetchJson } from '../../services/http'
import { useI18n } from '../useI18n'
import type { User, ClassInfo, School } from '@my-modern-app/shared-types'

export function useAuthActions(
  user: { value: User | null },
  loading: { value: boolean },
  error: { value: string | null },
  clearGuestState: () => void,
  setSchoolSession?: (s: School | null) => void,
) {
  const { t } = useI18n()
  function extractStatusCode(err: unknown): number | null {
    const msg = err instanceof Error ? err.message : String(err)
    const match = msg.match(/Request failed:\s*(\d{3})\b/)
    return match ? Number(match[1]) : null
  }

  function isNetworkError(err: unknown): boolean {
    const msg = err instanceof Error ? err.message : String(err)
    return msg.includes('Failed to fetch') || msg.includes('fetch failed')
  }

  async function login(email: string, password: string) {
    loading.value = true
    error.value = null
    try {
      const data = await fetchJson<{ success: boolean; user?: User; school?: School }>('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      })
      clearGuestState()
      if (data.school) {
        if (setSchoolSession) setSchoolSession(data.school)
        return { ok: true, school: data.school } as any
      }
      if (data.user) {
        user.value = data.user
        return true
      }
      return false
    } catch (err) {
      const status = extractStatusCode(err)
      if (status === 401) error.value = t('auth.errors.invalidCredentials')
      else if (isNetworkError(err)) error.value = t('auth.errors.cannotConnectToServer')
      else error.value = t('auth.errors.serverConnectionError')
      return false
    } finally {
      loading.value = false
    }
  }

  async function registerWithRole(email: string, password: string, name: string, roleVal: 'teacher' | 'student', schoolCode?: string) {
    loading.value = true
    error.value = null
    try {
      const body: Record<string, string> = { email, password, name, role: roleVal }
      if (schoolCode) body.school_code = schoolCode
      const data = await fetchJson<{ success: boolean; user?: User; devVerificationCode?: string }>('/api/auth/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })
      if (!data.success || !data.user) {
        error.value = t('auth.errors.registerFailed')
        return { ok: false as const, devCode: null as string | null }
      }
      clearGuestState()
      return { ok: true as const, devCode: data.devVerificationCode ?? null }
    } catch (err) {
      const status = extractStatusCode(err)
      if (status === 409) error.value = t('auth.errors.emailAlreadyUsed')
      else if (status === 400) error.value = t('auth.errors.invalidRegistrationData')
      else if (isNetworkError(err)) error.value = t('auth.errors.cannotConnectToServer')
      else error.value = t('auth.errors.registerFailed')
      return { ok: false as const, devCode: null as string | null }
    } finally {
      loading.value = false
    }
  }

  async function fetchMe() {
    try {
      const data = await fetchJson<{ user: User }>('/api/auth/me')
      user.value = data.user
    } catch {
      logout()
    }
  }

  async function init() {
    try {
      const data = await fetchJson<{ user: User }>('/api/auth/me')
      user.value = data.user
    } catch {
      // auth failed (token expired and refresh failed) — clear user to force re-login
      user.value = null
    }
  }

  async function tryRestore() {
    try {
      const data = await fetchJson<{ user: User }>('/api/auth/me')
      user.value = data.user
      return true
    } catch {
      return false
    }
  }

  async function updateProfileName(name: string) {
    loading.value = true
    error.value = null
    try {
      const data = await fetchJson<{ success: boolean; user?: User; message?: string }>('/api/auth/profile', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      })
      if (!data.success || !data.user) {
        return { ok: false as const, message: data.message || t('auth.errors.serverConnectionError') }
      }
      user.value = data.user
      return { ok: true as const, message: '' }
    } catch (err) {
      if (isNetworkError(err)) return { ok: false as const, message: t('auth.errors.cannotConnectToServer') }
      return { ok: false as const, message: t('auth.errors.serverConnectionError') }
    } finally {
      loading.value = false
    }
  }

  async function submitNameRequest(requestedName: string) {
    loading.value = true
    error.value = null
    try {
      const data = await fetchJson<{ success: boolean; message?: string }>('/api/auth/name-request', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ requested_name: requestedName }),
      })
      if (!data.success) {
        return { ok: false as const, message: data.message || t('auth.errors.serverConnectionError') }
      }
      return { ok: true as const, message: '' }
    } catch (err) {
      if (isNetworkError(err)) return { ok: false as const, message: t('auth.errors.cannotConnectToServer') }
      return { ok: false as const, message: t('auth.errors.serverConnectionError') }
    } finally {
      loading.value = false
    }
  }

  async function deleteMyAccount(password: string) {
    loading.value = true
    error.value = null
    try {
      const data = await fetchJson<{ success: boolean; message?: string }>('/api/auth/account', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password }),
      })
      if (!data.success) {
        return { ok: false as const, message: data.message || t('auth.errors.serverConnectionError') }
      }
      user.value = null
      return { ok: true as const, message: '' }
    } catch (err) {
      const status = extractStatusCode(err)
      if (status === 403) return { ok: false as const, message: t('account.wrongPassword') }
      if (isNetworkError(err)) return { ok: false as const, message: t('auth.errors.cannotConnectToServer') }
      return { ok: false as const, message: t('auth.errors.serverConnectionError') }
    } finally {
      loading.value = false
    }
  }

  async function updatePassword(userId: number, newPassword: string) {
    if (user.value?.id !== userId && user.value?.role !== 'admin') return false
    try {
      await fetchJson('/api/auth/password', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ user_id: userId, new_password: newPassword }),
      })
      return true
    } catch {
      return false
    }
  }

  async function joinClass(classCode: string, classes: { value: ClassInfo[] }, currentClassId: { value: string | null }) {
    loading.value = true
    error.value = null
    try {
      const data = await fetchJson<{ class_id: string; name: string; code: string; already_joined?: boolean }>('/api/classes/join', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: classCode, student_id: user.value?.id }),
      })
      const cls: ClassInfo = {
        id: data.class_id || classCode,
        name: data.name || classCode,
        code: classCode,
        role: 'student',
      }
      if (!classes.value.find((c) => c.code === classCode)) {
        classes.value.push(cls)
      }
      currentClassId.value = cls.id
      return true
    } catch (err) {
      const status = extractStatusCode(err)
      if (status === 404) error.value = t('auth.errors.invalidCode')
      else if (isNetworkError(err)) error.value = t('auth.errors.cannotConnectToServer')
      else error.value = t('auth.errors.serverConnectionError')
      return false
    } finally {
      loading.value = false
    }
  }

  async function createClass(className: string, classes: { value: ClassInfo[] }, currentClassId: { value: string | null }) {
    loading.value = true
    error.value = null
    try {
      const data = await fetchJson<{ id: string; name: string; code: string }>('/api/classes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: className, teacher_id: user.value?.id }),
      })
      const cls: ClassInfo = {
        id: data.id || data.code,
        name: className,
        code: data.code,
        role: 'teacher',
      }
      classes.value.push(cls)
      currentClassId.value = cls.id
      return data.code
    } catch (err) {
      console.error('createClass failed:', err)
      error.value = 'Server connection error'
      return null
    } finally {
      loading.value = false
    }
  }

  function selectClass(classId: string, currentClassId: { value: string | null }) {
    currentClassId.value = classId
  }

  async function logout() {
    try {
      await fetchJson('/api/auth/logout', { method: 'POST' })
    } catch {
      // ignore
    }
    clearGuestState()
    user.value = null
  }

  function setSession(u: User) {
    user.value = u
    clearGuestState()
  }

  return {
    login,
    registerWithRole,
    fetchMe,
    init,
    tryRestore,
    updatePassword,
    updateProfileName,
    submitNameRequest,
    deleteMyAccount,
    joinClass,
    createClass,
    selectClass,
    logout,
    setSession,
  }
}

import { ref, onMounted, onUnmounted } from 'vue';

/* ───────────── types ───────────── */
export interface MonitorSnapshot {
  fps: number;
  memoryUsed: number;
  memoryLimit: number;
  consoleErrors: number;
  consoleWarns: number;
  canvasErrors: number;
  physicsHealth: 'ok' | 'warn' | 'fail';
  chemistryHealth: 'ok' | 'warn' | 'fail';
  hasNaN: boolean;
  hasInfinity: boolean;
  time: string;
}

/* ───────────── reactive state ───────────── */
const fps = ref(0);
const memoryUsed = ref(0);
const memoryLimit = ref(0);
const consoleErrors = ref(0);
const consoleWarns = ref(0);
const canvasErrors = ref(0);
const physicsHealth = ref<'ok' | 'warn' | 'fail'>('ok');
const chemistryHealth = ref<'ok' | 'warn' | 'fail'>('ok');
const logs = ref<{ type: 'error' | 'warn' | 'info'; text: string; time: string }[]>([]);
const history = ref<MonitorSnapshot[]>([]);

let frameCount = 0;
let lastTime = performance.now();
let rafId = 0;
let memTimer = 0;
let historyTimer = 0;
let windowErrorHandler: ((e: ErrorEvent) => void) | null = null;

/* ── intercept console ── */
const origErr = console.error;
const origWarn = console.warn;
let consoleHookCount = 0;

function addLog(type: 'error' | 'warn' | 'info', args: unknown[]) {
  const text = args.map((a) => (typeof a === 'string' ? a : String(a))).join(' ');
  logs.value.unshift({ type, text, time: new Date().toLocaleTimeString('en-GB') });
  if (logs.value.length > 50) logs.value.pop();
}

function hookConsole() {
  if (consoleHookCount++ > 0) return;
  console.error = (...args: unknown[]) => {
    consoleErrors.value++;
    addLog('error', args);
    origErr.apply(console, args);
  };
  console.warn = (...args: unknown[]) => {
    consoleWarns.value++;
    addLog('warn', args);
    origWarn.apply(console, args);
  };
}

function unhookConsole() {
  if (--consoleHookCount > 0) return;
  consoleHookCount = 0;
  console.error = origErr;
  console.warn = origWarn;
}

/* ── hook window.onerror ── */
function onWindowError(e: ErrorEvent) {
  consoleErrors.value++;
  addLog('error', [e.message]);
}

/* ── hook Canvas & WebGL ── */
let canvasHookInstalled = false;
const wrapped2dContexts = new WeakSet<CanvasRenderingContext2D>();
const wrappedGlContexts = new WeakSet<WebGLRenderingContext>();

function hookCanvas() {
  if (canvasHookInstalled) return;
  canvasHookInstalled = true;
  const origGetContext = HTMLCanvasElement.prototype.getContext;
  (HTMLCanvasElement.prototype as any).getContext = function (
    contextId: string,
    options?: unknown
  ) {
    const ctx = (origGetContext as any).call(this, contextId, options);
    if (!ctx) return null;
    if (contextId === '2d') {
      const c2d = ctx as CanvasRenderingContext2D;
      if (wrapped2dContexts.has(c2d)) return ctx;
      wrapped2dContexts.add(c2d);
      const origFill = c2d.fillRect;
      c2d.fillRect = function (x: number, y: number, w: number, h: number) {
        try { return origFill.call(this, x, y, w, h); }
        catch (e) { canvasErrors.value++; throw e; }
      };
    }
    if (contextId === 'webgl' || contextId === 'webgl2') {
      const gl = ctx as WebGLRenderingContext;
      if (wrappedGlContexts.has(gl)) return ctx;
      wrappedGlContexts.add(gl);
      const origDraw = gl.drawArrays;
      gl.drawArrays = function (mode: number, first: number, count: number) {
        try { return origDraw.call(this, mode, first, count); }
        catch (e) { canvasErrors.value++; throw e; }
      };
    }
    return ctx;
  };
}

/* ── FPS loop ── */
function tick() {
  const t = performance.now();
  frameCount++;
  if (t - lastTime >= 1000) {
    fps.value = frameCount;
    frameCount = 0;
    lastTime = t;
    checkPhysicsHealth();
  }
  rafId = requestAnimationFrame(tick);
}

/* ── memory ── */
function readMemory() {
  const p = performance as Performance & { memory?: { usedJSHeapSize: number; jsHeapSizeLimit: number } }
  if (p.memory) {
    memoryUsed.value = Math.round(p.memory.usedJSHeapSize / 1024 / 1024);
    memoryLimit.value = Math.round(p.memory.jsHeapSizeLimit / 1024 / 1024);
  }
}

/* ── physics sanity checks ── */
function checkPhysicsHealth() {
  const w = window as Window & { __PHYSICS_VALUES__?: number[] }
  if (w.__PHYSICS_VALUES__) {
    const vals = w.__PHYSICS_VALUES__;
    const hasNaN = vals.some((v) => Number.isNaN(v));
    const hasInf = vals.some((v) => !Number.isFinite(v));
    if (hasNaN || hasInf) {
      physicsHealth.value = 'fail';
      addLog('error', ['Physics value became NaN or Infinity']);
    } else {
      physicsHealth.value = 'ok';
    }
  }
}

/* ── push snapshot ── */
function pushSnapshot() {
  history.value.push({
    fps: fps.value,
    memoryUsed: memoryUsed.value,
    memoryLimit: memoryLimit.value,
    consoleErrors: consoleErrors.value,
    consoleWarns: consoleWarns.value,
    canvasErrors: canvasErrors.value,
    physicsHealth: physicsHealth.value,
    chemistryHealth: chemistryHealth.value,
    hasNaN: false,
    hasInfinity: false,
    time: new Date().toLocaleTimeString('en-GB'),
  });
  if (history.value.length > 60) history.value.shift();
}

/* ── public API ── */
export function useExperimentMonitor() {
  onMounted(() => {
    hookConsole();
    windowErrorHandler = (e: ErrorEvent) => onWindowError(e);
    window.addEventListener('error', windowErrorHandler);
    hookCanvas();
    rafId = requestAnimationFrame(tick);
    memTimer = window.setInterval(readMemory, 2000);
    historyTimer = window.setInterval(pushSnapshot, 5000);
  });

  onUnmounted(() => {
    cancelAnimationFrame(rafId);
    clearInterval(memTimer);
    clearInterval(historyTimer);
    unhookConsole();
    if (windowErrorHandler) {
      window.removeEventListener('error', windowErrorHandler);
      windowErrorHandler = null;
    }
  });

  return {
    fps,
    memoryUsed,
    memoryLimit,
    consoleErrors,
    consoleWarns,
    canvasErrors,
    physicsHealth,
    chemistryHealth,
    logs,
    history,
  };
}

/* ── helper for experiment code to push values ── */
export function pushPhysicsValues(values: number[]) {
  (window as Window & { __PHYSICS_VALUES__?: number[] }).__PHYSICS_VALUES__ = values;
}

﻿<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, watch } from 'vue'
import { useI18n } from '../../../../../composables/useI18n'
import { useWorkshop } from '../shared/useWorkshop'
import { useWorkshopCanvas } from '../shared/useWorkshopCanvas'
import { getSpec } from '../shared/componentSpecs'
import { useResistorData } from '../shared/useResistorData'
import { useCircuitDialogs } from '../shared/useCircuitDialogs'
import { useComponentEditor } from '../shared/useComponentEditor'
import { useEditActions } from '../shared/useEditActions'
import { useSelectionSync } from '../shared/useSelectionSync'
import { useAnimationLoop } from '../shared/useAnimationLoop'
import { createRedraw, resizeCanvas as _resizeCanvas } from '../shared/workshopRedraw'
import { exportPNG as _exportPNG, openCanvasFullscreen as _openCanvasFullscreen, printCircuit as _printCircuit } from '../shared/workshopExport'
import { useLabActions } from '../shared/useLabActions'
import type { WorkshopComponent, WorkshopWire } from '../shared/types'
import { buildACCalcExplanation } from './acExplainCalcs'
import { createACCanvasState, type ACCanvasState } from './acCanvasState'
import { onMouseDown, onMouseMove, onMouseUp } from './acMouseEvents'
import { onWheel, onDblClick, onTouchStart, onTouchMove, onTouchEnd, onKeyDown } from './acOtherEvents'
import { useDevice } from '../../../../../composables/useDevice'
import ACDialogs from './ACDialogs.vue'
import ACReadingsPanel from './ACReadingsPanel.vue'
import ACPalette from './ACPalette.vue'
import ACTopBar from './ACTopBar.vue'
import ACBottomBar from './ACBottomBar.vue'

const workshop = useWorkshop('ac')
const device = useDevice()
const { t } = useI18n()
const canvasRef = ref<HTMLCanvasElement | null>(null)
const zoom = ref(1)
const panX = ref(0)
const panY = ref(0)

const dragState: ACCanvasState = { wireStart: null, junctionStart: null, tempWireEnd: { x: 0, y: 0 }, hoverWireId: null, pendingWireStart: null } as any

const showValueEditor = ref(false)
const editingComp = ref<WorkshopComponent | null>(null)
const editValue = ref(0)
const editRotation = ref(0)

const showWireEditor = ref(false)
const editingWire = ref<WorkshopWire | null>(null)
const editWireColor = ref('')
const editWireThickness = ref(3)

const showExperiments = ref(false)
const currentExperiment = ref<'ac_rl' | 'ac_rc' | 'ac_rlc' | 'ac_transformer' | 'ac_filter' | 'ac_powerfactor' | 'ac_resonance' | null>(null)
const showCalcExplanation = ref(false)
const calcExplanationHtml = ref('')
const canvasSnapshot = ref('')
const runStartTime = ref(0)
const canvasFullscreen = ref(false)
const renderMode = ref<'3d' | '2d'>('3d')
const showNodeNumbers = ref(false)
const showReadings = ref(false)
const showResistorTutorial = ref(false)
const showHelp = ref(false)
const selectedFault = ref<any>(null)

watch(() => workshop.faults.value, (newFaults) => {
  if (selectedFault.value && !newFaults.some(f => f.componentId === selectedFault.value.componentId && f.type === selectedFault.value.type)) {
    selectedFault.value = null
  }
})

const { resistorBandPreview, resistorBandExplanation, resistorColorChart } = useResistorData(editingComp)
const { showSaveDialog, showLoadDialog, circuitName, savedCircuits, doSaveCircuit, openLoadDialog, doDeleteCircuit } = useCircuitDialogs(workshop)

const animTime = ref(0)
const wireCurrents = computed(() => {
  const map = new Map<number, number>()
  for (const wire of workshop.wires) {
    const fromComp = workshop.components.find(c => c.id === wire.fromCompId)
    if (fromComp) map.set(wire.id, fromComp.current)
  }
  return map
})

const canvasProps = {
  get components() { return workshop.components },
  get wires() { return workshop.wires },
  get running() { return workshop.running.value },
  get selectedWireColor() { return workshop.selectedWireColor.value },
  get renderMode() { return renderMode.value },
  get animTime() { return animTime.value },
  get wireCurrents() { return wireCurrents.value },
  get showNodeNumbers() { return showNodeNumbers.value },
  get showReadings() { return showReadings.value },
  t,
}

const { worldToScreen, screenToWorld, hitTestComponent, hitTestTerminal: _hitTestTerminal, hitTestWire, hitTestWireJunction, hitTestWireSegment, hitTestProbe, hitTestClamp, draw } = useWorkshopCanvas(
  zoom, panX, panY, canvasProps,
)

const hitTestTerminal = (sx: number, sy: number) => _hitTestTerminal(sx, sy, device.value.hitRadius)

const { redraw: _redraw } = createRedraw(canvasRef, zoom, panX, panY, workshop, dragState, { worldToScreen, draw })
function redraw() { _redraw() }
function resizeCanvas() { _resizeCanvas(canvasRef, redraw) }

function onAddComponent(type: string) {
  const c = canvasRef.value; if (!c) return
  const x = c.width / 2 - panX.value
  const y = c.height / 2 - panY.value
  workshop.addComponent(type as any, x / zoom.value, y / zoom.value)
  redraw()
}

function loadExp(name: 'ac_rl' | 'ac_rc' | 'ac_rlc' | 'ac_transformer' | 'ac_filter' | 'ac_powerfactor' | 'ac_resonance') {
  currentExperiment.value = name
  showExperiments.value = false
  try {
    workshop.loadExperiment(name)
  } catch (e) {
    if (import.meta.env.DEV) console.error('loadExperiment error:', e)
  }
