import { describe, it, expect } from 'vitest'
import { solveCircuit } from './solver-dc'
import type { WorkshopComponent, WorkshopWire } from './types'

function makeComp(opts: Partial<WorkshopComponent> & { type: string; x: number; y: number }): WorkshopComponent {
  return {
    id: Math.floor(Math.random() * 100000),
    type: opts.type as any,
    x: opts.x,
    y: opts.y,
    rotation: 0,
    value: opts.value ?? 0,
    unit: '',
    label: opts.type,
    closed: opts.closed ?? true,
    terminals: [],
    voltage: 0,
    current: 0,
    breakerTripped: false,
    fuseBlown: false,
    relayState: false,
    breakerRating: 0,
  } as any
}

function term(compId: number, index: number, dx: number, dy: number) {
  return { id: compId * 100 + index, compId, index, dx, dy, nodeId: 0, worldX: 0, worldY: 0 }
}

function wire(id: number, fromComp: number, fromTerm: number, toComp: number, toTerm: number): WorkshopWire {
  return { id, fromCompId: fromComp, fromTerminalIndex: fromTerm, toCompId: toComp, toTerminalIndex: toTerm, color: '#3b82f6', thickness: 2, points: [] }
}

describe('Switch + Lamp integration', () => {
  it('lamp should be OFF when switch is OPEN', () => {
    const bat = makeComp({ type: 'battery', x: 0, y: 0, value: 9 })
    bat.terminals = [term(bat.id, 0, -20, 0), term(bat.id, 1, 20, 0)]

    const sw = makeComp({ type: 'switch', x: 100, y: 0, value: 0, closed: false })
    sw.terminals = [term(sw.id, 0, -15, 0), term(sw.id, 1, 15, 0)]

    const lamp = makeComp({ type: 'lamp', x: 200, y: 0, value: 6 })
    lamp.terminals = [term(lamp.id, 0, -15, 0), term(lamp.id, 1, 15, 0)]

    const wires: WorkshopWire[] = [
      wire(1, bat.id, 0, sw.id, 0),   // bat+ → switch T0
      wire(2, sw.id, 1, lamp.id, 0),  // switch T1 → lamp T0
      wire(3, lamp.id, 1, bat.id, 1), // lamp T1 → bat-
    ]

    const result = solveCircuit([bat, sw, lamp], wires)
    expect(result.converged).toBe(true)

    const lampV = result.componentVoltages.get(lamp.id) ?? 999
    const lampI = result.componentCurrents.get(lamp.id) ?? 999
    const lampPower = Math.abs(lampV * lampI)
    expect(Math.abs(lampI)).toBeLessThan(1e-6)
    expect(lampPower).toBeLessThan(1e-6)
  })

  it('lamp should be ON when switch is CLOSED', () => {
    const bat = makeComp({ type: 'battery', x: 0, y: 0, value: 9 })
    bat.terminals = [term(bat.id, 0, -20, 0), term(bat.id, 1, 20, 0)]

    const sw = makeComp({ type: 'switch', x: 100, y: 0, value: 0, closed: true })
    sw.terminals = [term(sw.id, 0, -15, 0), term(sw.id, 1, 15, 0)]

    const lamp = makeComp({ type: 'lamp', x: 200, y: 0, value: 6 })
    lamp.terminals = [term(lamp.id, 0, -15, 0), term(lamp.id, 1, 15, 0)]

    const wires: WorkshopWire[] = [
      wire(1, bat.id, 0, sw.id, 0),
      wire(2, sw.id, 1, lamp.id, 0),
      wire(3, lamp.id, 1, bat.id, 1),
    ]

    const result = solveCircuit([bat, sw, lamp], wires)
    expect(result.converged).toBe(true)

    const lampV = result.componentVoltages.get(lamp.id) ?? 0
    const lampI = result.componentCurrents.get(lamp.id) ?? 0
    const lampPower = Math.abs(lampV * lampI)
    expect(Math.abs(lampI)).toBeGreaterThan(0.01)
  })
})

import type { Ref } from 'vue'
import type { useWorkshop } from './useWorkshop'
import type { WorkshopComponent, WorkshopWire } from './types'

type Workshop = ReturnType<typeof useWorkshop>

export function useComponentEditor(
  workshop: Workshop,
  redraw: () => void,
  selectedFault: Ref<any>,
) {
  function applyEditValue(editingComp: Ref<WorkshopComponent | null>, editValue: Ref<number>) {
    if (editingComp.value) {
      workshop.updateComponentValue(editingComp.value.id, editValue.value)
      if (workshop.running.value) {
        workshop.solve()
      } else {
        workshop.faults.value = []
      }
      redraw()
    }
  }

  function applyRotate(editingComp: Ref<WorkshopComponent | null>, editRotation: Ref<number>) {
    if (editingComp.value) {
      workshop.pushUndo()
      while (editingComp.value.rotation !== editRotation.value) {
        workshop.rotateComponent(editingComp.value.id)
      }
      workshop.rerouteAllWires()
      if (workshop.running.value) workshop.solve()
      redraw()
    }
  }

  function zoomComp(editingComp: Ref<WorkshopComponent | null>, delta: number) {
    if (editingComp.value) {
      const cur = editingComp.value.scale ?? 1
      workshop.setComponentScale(editingComp.value.id, cur + delta)
      workshop.rerouteAllWires()
      redraw()
    }
  }

  function zoomCompVal(editingComp: Ref<WorkshopComponent | null>, val: number) {
    if (editingComp.value) {
      workshop.setComponentScale(editingComp.value.id, val)
      workshop.rerouteAllWires()
      redraw()
    }
  }

  function deleteSelectedComp() {
    if (workshop.selectedComponentId.value !== null) {
      workshop.removeComponent(workshop.selectedComponentId.value)
      if (workshop.running.value) {
        workshop.solve()
      } else {
        workshop.faults.value = []
      }
      selectedFault.value = null
      redraw()
    }
  }

  function deleteSelectedWire(
    showWireEditor: Ref<boolean>,
    editingWire: Ref<WorkshopWire | null>,
  ) {
    if (workshop.selectedWireId.value !== null) {
      workshop.removeWire(workshop.selectedWireId.value)
      if (workshop.running.value) {
        workshop.solve()
      } else {
        workshop.faults.value = []
      }
      showWireEditor.value = false
      editingWire.value = null
      redraw()
    }
  }

  return {
    applyEditValue,
    applyRotate,
    zoomComp,
    zoomCompVal,
    deleteSelectedComp,
    deleteSelectedWire,
  }
}

import { ref, reactive, computed, watch } from 'vue'
import type { WorkshopComponent, WorkshopWire, ComponentType, SolveResult, FaultInfo, TransientResult } from './types'
import { WIRE_COLORS } from './types'
import { solve as solverSolve, solveAC as solverSolveAC, solveTransient as solverSolveTransient, solveTransientDC as solverSolveTransientDC, getPower as solverGetPower, type SolverContext } from './workshopSolver'
import {
  STORAGE_KEY_DC, STORAGE_KEY_AC,
  saveState, loadState, saveCircuit as storageSaveCircuit,
  getSavedCircuits as storageGetSavedCircuits,
  deleteCircuit as storageDeleteCircuit,
  loadCircuitData,
} from './workshopStorage'
import { WorkshopHistory } from './workshopHistory'
import { loadDCExperiment, type ExperimentName } from './workshopExperimentsDC'
import { loadACExperiment, type ACExperimentName } from './workshopExperimentsAC'
import * as compOps from './workshopComponents'
import * as wireOps from './workshopWires'

export function useWorkshop(labId: 'dc' | 'ac' = 'dc') {
  const storageKey = labId === 'ac' ? STORAGE_KEY_AC : STORAGE_KEY_DC
  const saved = loadState(storageKey)
  const idCounterRef = { value: saved?.idCounter || 1 }

  const components = reactive<WorkshopComponent[]>(saved?.components ?? [])
  const wires = reactive<WorkshopWire[]>(saved?.wires ?? [])
  const running = ref(false)
  const selectedComponentId = ref<number | null>(null)
  const selectedWireId = ref<number | null>(null)
  const selectedWireColor = ref(WIRE_COLORS.blue)
  const selectedWireThickness = ref(3)
  const solveResult = ref<SolveResult | null>(null)
  const error = ref('')
  const faults = ref<FaultInfo[]>([])

  const history = new WorkshopHistory(
    () => components,
    () => wires,
    () => idCounterRef.value,
    (n) => { idCounterRef.value = n },
  )

  function pushUndo() { history.pushUndo() }

  function undo() {
    history.undo(components, wires)
    selectedComponentId.value = null
    selectedWireId.value = null
    if (running.value) solve()
  }

  function redo() {
    history.redo(components, wires)
    selectedComponentId.value = null
    selectedWireId.value = null
    if (running.value) solve()
  }

  let saveTimer: ReturnType<typeof setTimeout> | null = null
  watch([() => [...components], () => [...wires]], () => {
    if (saveTimer) clearTimeout(saveTimer)
    saveTimer = setTimeout(() => saveState(components, wires, storageKey, idCounterRef.value), 500)
  }, { deep: true })

  const compCtx: compOps.ComponentOpsContext = {
    components, wires, idCounter: idCounterRef,
    selectedComponentId,
    selectedWireThickness,
    pushUndo,
    addWire: (fc, ft, tc, tt, c, mp?) => addWire(fc, ft, tc, tt, c, mp),
    rerouteAllWires: () => rerouteAllWires(),
  }

  const wireCtx: wireOps.WireOpsContext = {
    components, wires, idCounter: idCounterRef,
    selectedWireId, selectedWireThickness,
    pushUndo,
  }

  function addComponent(type: ComponentType, x: number, y: number) {
    compOps.addComponent(compCtx, type, x, y)
  }
  function moveComponent(id: number, x: number, y: number) {
    compOps.moveComponent(compCtx, id, x, y)
  }
  function rotateComponent(id: number) {
    compOps.rotateComponent(compCtx, id)
  }
  function setComponentScale(id: number, scale: number) {
    compOps.setComponentScale(compCtx, id, scale)
  }
  function removeComponent(id: number) {
    compOps.removeComponent(compCtx, id)
    if (running.value) solve()
  }
  function insertAmmeterIntoWire(wireId: number, ammeterId: number) {
    compOps.insertAmmeterIntoWire(compCtx, wireId, ammeterId)
  }
  function updateComponentValue(id: number, value: number) {
    compOps.updateComponentValue(compCtx, id, value)
  }
  function toggleSwitch(id: number) {
    compOps.toggleSwitch(compCtx, id)
    if (running.value) solve()
  }
  function toggleRelay(id: number) {
    const comp = components.find(c => c.id === id)
    if (comp && comp.type === 'relay') {
      pushUndo()
      comp.relayState = !comp.relayState
      comp.relayManualOverride = true
      if (running.value) solve()
    }
  }
  function setMultimeterMode(id: number, mode: 'voltage' | 'current' | 'resistance') {
    compOps.setMultimeterMode(compCtx, id, mode, running.value, solve)
  }
  function resetBreaker(id: number) {
    compOps.resetBreaker(compCtx, id)
  }
  function resetFuse(id: number) {
    compOps.resetFuse(compCtx, id)
  }

  function addWire(
    fromCompId: number, fromTermIndex: number,
    toCompId: number, toTermIndex: number,
    color: string,
    manualPoints?: { x: number; y: number }[],
  ) {
    wireOps.addWire(wireCtx, fromCompId, fromTermIndex, toCompId, toTermIndex, color, manualPoints)
  }
  function addWireFromJunction(
    fromWireId: number, fromPointIndex: number,
    toCompId: number, toTermIndex: number,
    color: string,
  ) {
    wireOps.addWireFromJunction(wireCtx, fromWireId, fromPointIndex, toCompId, toTermIndex, color)
  }
  function removeWire(id: number) {
    wireOps.removeWire(wireCtx, id)
    if (running.value) solve()
  }
  function updateWireColor(id: number, color: string) {
    wireOps.updateWireColor(wireCtx, id, color)
  }
  function updateWireThickness(id: number, thickness: number) {
    wireOps.updateWireThickness(wireCtx, id, thickness)
  }
  function moveWirePoint(wireId: number, pointIndex: number, x: number, y: number) {
    wireOps.moveWirePoint(wireCtx, wireId, pointIndex, x, y)
  }
  function rerouteAllWires() {
    wireOps.rerouteAllWires(wireCtx)
  }
  function rerouteWiresForComponent(compId: number) {
    wireOps.rerouteWiresForComponent(wireCtx, compId)
  }

  function clearAll() {
    pushUndo()
    components.splice(0, components.length)
    wires.splice(0, wires.length)
    selectedComponentId.value = null
    selectedWireId.value = null
    solveResult.value = null
    error.value = ''
    faults.value = []
    try { localStorage.removeItem(storageKey) } catch (e) { /* ignore */ }
  }

  function saveCircuit(name: string): boolean {
    return storageSaveCircuit(name, components, wires, idCounterRef.value)
  }

  function loadCircuit(name: string): boolean {
    pushUndo()
    const data = loadCircuitData(name)
    if (!data) return false
    clearAll()
    idCounterRef.value = data.idCounter ?? 1
    for (const c of data.components) {
      components.push({ ...c, terminals: c.terminals.map((t: any) => ({ ...t })) })
    }
    for (const w of data.wires) {
      wires.push({ ...w, points: [...w.points] })
    }
    if (running.value) solve()
    return true
  }

  function getSavedCircuits(): string[] {
    return storageGetSavedCircuits()
  }

  function deleteCircuit(name: string): boolean {
    return storageDeleteCircuit(name)
  }

  function loadExperiment(name: ExperimentName | ACExperimentName) {
    pushUndo()
    clearAll()

    const ctx = { components, wires, addComponent, rotateComponent, addWire }

    const dcNames: string[] = ['ohm', 'series', 'parallel', 'mixed', 'kvl', 'kcl', 'vdivider', 'cdivider', 'bseries', 'bparallel', 'relay', 'rc_charge', 'rl_transient', 'wheatstone', 'thevenin', 'superposition', 'maxpower']
    const acNames: string[] = ['ac_rl', 'ac_rc', 'ac_rlc', 'ac_transformer', 'ac_filter', 'ac_powerfactor', 'ac_resonance']

    if (dcNames.includes(name)) {
      loadDCExperiment(name as ExperimentName, ctx)
    } else if (acNames.includes(name)) {
      loadACExperiment(name as ACExperimentName, ctx)
    }

    const firstBat = components.find(c => c.type === 'battery')
    const hasGround = components.some(c => c.type === 'ground')
    if (firstBat && !hasGround) {
      const negTerm = firstBat.terminals.find(t => t.index === 1)
      if (negTerm) {
        const gx = firstBat.x + negTerm.dx + 40
        const gy = firstBat.y + negTerm.dy + 40
        addComponent('ground', gx, gy)
        const gnd = components[components.length - 1]
        addWire(gnd.id, 0, firstBat.id, 1, WIRE_COLORS.black, [])
      }
    }

    selectedComponentId.value = null
    selectedWireId.value = null
  }

  function run() {
    running.value = true
    if (isACMode.value) {
      solveAC()
      solveTransient()
    } else {
      solve()
      solveTransientDC()
    }
  }

  function stop() {
    running.value = false
    for (const comp of components) {
      comp.voltage = 0
      comp.current = 0
    }
    faults.value = []
  }

  const isACMode = computed(() => components.some(c => c.type === 'acsource'))

  const solverCtx: SolverContext = {
    components, wires, solveResult, error, faults, isACMode,
  }

  function solve() { solverSolve(solverCtx) }
  function solveAC() { solverSolveAC(solverCtx) }
  function solveTransient(): TransientResult | null { return solverSolveTransient(solverCtx) }
  function solveTransientDC(): TransientResult | null { return solverSolveTransientDC(solverCtx) }
  function getPower(comp: WorkshopComponent): number { return solverGetPower(comp) }

  const totalPower = computed(() => {
    let p = 0
    for (const comp of components) {
      if (comp.type === 'resistor' || comp.type === 'lamp' || comp.type === 'led' || comp.type === 'motor' || comp.type === 'potentiometer') p += getPower(comp)
      if (comp.type === 'relay') p += getPower(comp)
    }
    return p
  })

  const totalCurrent = computed(() => {
    for (const comp of components) {
      if (comp.type === 'battery' || comp.type === 'acsource') {
        return Math.abs(comp.current)
      }
    }
    return 0
  })

  const totalVoltage = computed(() => {
    const sources = components.filter(c => c.type === 'battery' || c.type === 'acsource')
    if (sources.length === 0) return 0
    if (sources.length === 1) return sources[0].value
    const allSameNode = sources.every((s, i, arr) => {
      if (i === 0) return true
      return s.terminals[0]?.nodeId === arr[0].terminals[0]?.nodeId &&
             s.terminals[1]?.nodeId === arr[0].terminals[1]?.nodeId
    })
    if (allSameNode) {
      return Math.max(...sources.map(s => s.value))
    }
    return sources.reduce((sum, s) => sum + s.value, 0)
  })

  return {
    components, wires, running,
    selectedComponentId, selectedWireId, selectedWireColor,
    solveResult, error,
    addComponent, moveComponent, rotateComponent, setComponentScale,
    removeComponent, insertAmmeterIntoWire,
    updateComponentValue, toggleSwitch, toggleRelay, setMultimeterMode,
    resetBreaker, resetFuse,
    addWire, addWireFromJunction, removeWire,
    updateWireColor, updateWireThickness, moveWirePoint,
    rerouteAllWires, rerouteWiresForComponent,
    clearAll, saveCircuit, loadCircuit, getSavedCircuits, deleteCircuit,
    loadExperiment, run, stop, solve, solveAC, solveTransient, solveTransientDC,
    isACMode, faults, selectedWireThickness,
    getPower, totalPower, totalCurrent, totalVoltage,
    undo, redo, pushUndo,
    canUndo: history.canUndo,
    canRedo: history.canRedo,
  }
}

import type { Ref } from 'vue'
import type { useWorkshop } from './useWorkshop'

type Workshop = ReturnType<typeof useWorkshop>

interface DragStateLike {
  wireStart: { comp: any; termIndex: number } | null
  junctionStart: { worldX: number; worldY: number } | null
  tempWireEnd: { x: number; y: number }
  hoverWireId: number | null
  pendingWireStart: { comp: any; termIndex: number } | null
}

interface CanvasHelpers {
  worldToScreen: (x: number, y: number) => [number, number]
  draw: (canvas: HTMLCanvasElement, selectedCompId: number | null, selectedWireId: number | null, tempW: any) => void
}

export function createRedraw(
  canvasRef: Ref<HTMLCanvasElement | null>,
  zoom: Ref<number>,
  panX: Ref<number>,
  panY: Ref<number>,
  workshop: Workshop,
  dragState: DragStateLike,
  helpers: CanvasHelpers,
) {
  function redraw() {
    if (!canvasRef.value) return
    const ds = dragState
    const tempW = ds.wireStart || ds.junctionStart || ds.pendingWireStart ? { fromX: 0, fromY: 0, toX: ds.tempWireEnd.x, toY: ds.tempWireEnd.y } : null
    if (ds.wireStart && canvasRef.value) {
      const ctx = canvasRef.value.getContext('2d')
      if (ctx) {
        const comp = ds.wireStart.comp
        const term = comp.terminals[ds.wireStart.termIndex]
        const s = comp.scale ?? 1
        const r = comp.rotation * Math.PI / 180
        const cos = Math.cos(r), sin = Math.sin(r)
        const dx = term.dx * s
        const dy = term.dy * s
        const wx = comp.x + dx * cos - dy * sin
        const wy = comp.y + dx * sin + dy * cos
        const [sfx, sfy] = [wx * zoom.value + panX.value, wy * zoom.value + panY.value]
        if (tempW) { tempW.fromX = sfx; tempW.fromY = sfy }
      }
    } else if (ds.junctionStart && canvasRef.value) {
      if (tempW) {
        tempW.fromX = ds.junctionStart.worldX * zoom.value + panX.value
        tempW.fromY = ds.junctionStart.worldY * zoom.value + panY.value
      }
    } else if (ds.pendingWireStart && canvasRef.value) {
      const ctx = canvasRef.value.getContext('2d')
      if (ctx) {
        const comp = ds.pendingWireStart.comp
        const term = comp.terminals[ds.pendingWireStart.termIndex]
        const s = comp.scale ?? 1
        const r = comp.rotation * Math.PI / 180
        const cos = Math.cos(r), sin = Math.sin(r)
        const dx = term.dx * s
        const dy = term.dy * s
        const wx = comp.x + dx * cos - dy * sin
        const wy = comp.y + dx * sin + dy * cos
        const [sfx, sfy] = [wx * zoom.value + panX.value, wy * zoom.value + panY.value]
        if (tempW) { tempW.fromX = sfx; tempW.fromY = sfy }
      }
    }
    helpers.draw(canvasRef.value, workshop.selectedComponentId.value, workshop.selectedWireId.value, tempW)

    // Highlight pending terminal with a pulsing ring
    if (ds.pendingWireStart && canvasRef.value) {
      const ctx = canvasRef.value.getContext('2d')
      if (ctx) {
        const comp = ds.pendingWireStart.comp
        const term = comp.terminals[ds.pendingWireStart.termIndex]
        const s = comp.scale ?? 1
        const r = comp.rotation * Math.PI / 180
        const cos = Math.cos(r), sin = Math.sin(r)
        const dx = term.dx * s
        const dy = term.dy * s
        const wx = comp.x + dx * cos - dy * sin
        const wy = comp.y + dx * sin + dy * cos
        const [tsx, tsy] = [wx * zoom.value + panX.value, wy * zoom.value + panY.value]
        ctx.strokeStyle = 'rgba(34,197,94,0.8)'
        ctx.lineWidth = 3 * zoom.value
        ctx.beginPath()
        ctx.arc(tsx, tsy, 12 * zoom.value, 0, Math.PI * 2)
        ctx.stroke()
        ctx.fillStyle = 'rgba(34,197,94,0.2)'
        ctx.fill()
      }
    }

    if (ds.hoverWireId !== null && canvasRef.value) {
      const ctx = canvasRef.value.getContext('2d')
      if (ctx) {
        const wire = workshop.wires.find(w => w.id === ds.hoverWireId)
        if (wire) {
          const fromComp = workshop.components.find(c => c.id === wire.fromCompId)
          const toComp = workshop.components.find(c => c.id === wire.toCompId)
          if (fromComp && toComp) {
            const fromTerm = fromComp.terminals[wire.fromTerminalIndex]
            const toTerm = toComp.terminals[wire.toTerminalIndex]
            if (fromTerm && toTerm) {
              const s = fromComp.scale ?? 1
              const r1 = fromComp.rotation * Math.PI / 180
              const r2 = toComp.rotation * Math.PI / 180
              const fwx = fromComp.x + fromTerm.dx * s * Math.cos(r1) - fromTerm.dy * s * Math.sin(r1)
              const fwy = fromComp.y + fromTerm.dx * s * Math.sin(r1) + fromTerm.dy * s * Math.cos(r1)
              const twx = toComp.x + toTerm.dx * s * Math.cos(r2) - toTerm.dy * s * Math.sin(r2)
              const twy = toComp.y + toTerm.dx * s * Math.sin(r2) + toTerm.dy * s * Math.cos(r2)
              ctx.strokeStyle = 'rgba(34,197,94,0.6)'
              ctx.lineWidth = 6 * zoom.value
              ctx.lineCap = 'round'
              ctx.beginPath()
              const [sfx, sfy] = helpers.worldToScreen(fwx, fwy)
              ctx.moveTo(sfx, sfy)
              for (const p of wire.points) {
                const [px, py] = helpers.worldToScreen(p.x, p.y)
                ctx.lineTo(px, py)
              }
              const [stx, sty] = helpers.worldToScreen(twx, twy)
              ctx.lineTo(stx, sty)
              ctx.stroke()
            }
          }
        }
      }
    }
  }

  return { redraw }
}

export function getMousePos(canvasRef: Ref<HTMLCanvasElement | null>, e: MouseEvent): [number, number] {
  const c = canvasRef.value; if (!c) return [0, 0]
  const rect = c.getBoundingClientRect()
  return [e.clientX - rect.left, e.clientY - rect.top]
}

export function resizeCanvas(canvasRef: Ref<HTMLCanvasElement | null>, redraw: () => void) {
  const c = canvasRef.value; if (!c) return
  const parent = c.parentElement; if (!parent) return
  c.width = parent.clientWidth
  c.height = parent.clientHeight
  redraw()
}

import type { WorkshopComponent, WorkshopWire } from './types'

export const STORAGE_KEY_DC = 'electric-workshop-state-dc'
export const STORAGE_KEY_AC = 'electric-workshop-state-ac'
export const STORAGE_VERSION = 1

export type PersistedWorkshopState = {
  version: number
  components: WorkshopComponent[]
  wires: WorkshopWire[]
  idCounter: number
}

export function saveState(
  components: WorkshopComponent[],
  wires: WorkshopWire[],
  storageKey: string,
  idCounter: number,
) {
  try {
    const data = {
      version: STORAGE_VERSION,
      components: components.map(c => ({ ...c, terminals: c.terminals.map(t => ({ ...t })) })),
      wires: wires.map(w => ({ ...w, points: [...w.points] })),
      idCounter,
    }
    localStorage.setItem(storageKey, JSON.stringify(data))
  } catch (e) {
    // ignore storage errors
  }
}

export function loadState(storageKey: string): PersistedWorkshopState | null {
  try {
    const raw = localStorage.getItem(storageKey)
    if (!raw) return null
    const data = JSON.parse(raw)
    if (!data || data.version !== STORAGE_VERSION || !data.components || !data.wires) {
      localStorage.removeItem(storageKey)
      return null
    }
    return { version: data.version, components: data.components, wires: data.wires, idCounter: data.idCounter }
  } catch (e) {
    try { localStorage.removeItem(storageKey) } catch { /* ignore */ }
    return null
  }
}

const CIRCUITS_KEY = 'electric-workshop-saved-circuits'

export function saveCircuit(
  name: string,
  components: WorkshopComponent[],
  wires: WorkshopWire[],
  idCounter: number,
): boolean {
  try {
    const raw = localStorage.getItem(CIRCUITS_KEY)
    const list: { name: string; data: any }[] = raw ? JSON.parse(raw) : []
    const data = {
      version: STORAGE_VERSION,
      components: components.map(c => ({ ...c, terminals: c.terminals.map(t => ({ ...t })) })),
      wires: wires.map(w => ({ ...w, points: [...w.points] })),
      idCounter,
    }
    const idx = list.findIndex(c => c.name === name)
    if (idx >= 0) list[idx].data = data
    else list.push({ name, data })
    localStorage.setItem(CIRCUITS_KEY, JSON.stringify(list))
    return true
  } catch (e) {
    return false
  }
}

export function getSavedCircuits(): string[] {
  try {
    const raw = localStorage.getItem(CIRCUITS_KEY)
    if (!raw) return []
    const list: { name: string; data: any }[] = JSON.parse(raw)
    return list.map(c => c.name)
  } catch (e) {
    return []
  }
}

export function deleteCircuit(name: string): boolean {
  try {
    const raw = localStorage.getItem(CIRCUITS_KEY)
    if (!raw) return false
    const list: { name: string; data: any }[] = JSON.parse(raw)
    const idx = list.findIndex(c => c.name === name)
    if (idx < 0) return false
    list.splice(idx, 1)
    localStorage.setItem(CIRCUITS_KEY, JSON.stringify(list))
    return true
  } catch (e) {
    return false
  }
}

export function loadCircuitData(name: string): PersistedWorkshopState | null {
  try {
    const raw = localStorage.getItem(CIRCUITS_KEY)
    if (!raw) return null
    const list: { name: string; data: any }[] = JSON.parse(raw)
    const found = list.find(c => c.name === name)
    if (!found) return null
    if (!found.data || found.data.version !== STORAGE_VERSION) return null
    return {
      version: found.data.version,
      components: found.data.components,
      wires: found.data.wires,
      idCounter: found.data.idCounter ?? 1,
    }
  } catch (e) {
    return null
  }
}

